def squad_workout(names):
    for name in names:
        print(f"{name} reports for training.")
    for round_num in range(1, 4):
        print(f"Round {round_num} complete.")
    initials = [name[0] for name in names]
    print("Initials:", initials)

squad_workout(["Nyx", "Bram", "Odele"])
